// ---- src/core/recovery.js ----
const RECOVERY_DB_NAME = 'zeter-photo-editor';
const RECOVERY_STORE_NAME = 'recovery';
const RECOVERY_KEY = 'latest';
const RECOVERY_RECORD_VERSION = 2;

function requestResult(request, timeoutMs = 5000) {
  return new Promise((resolve, reject) => {
    let settled = false;
    const timeout = setTimeout(() => {
      if (settled) return;
      settled = true;
      reject(new Error('Операция локального хранилища не ответила вовремя'));
    }, timeoutMs);
    request.onsuccess = () => {
      if (settled) return;
      settled = true;
      clearTimeout(timeout);
      resolve(request.result);
    };
    request.onerror = () => {
      if (settled) return;
      settled = true;
      clearTimeout(timeout);
      reject(request.error || new Error('Ошибка локального хранилища'));
    };
  });
}

function transactionDone(transaction, timeoutMs = 5000) {
  return new Promise((resolve, reject) => {
    let settled = false;
    const timeout = setTimeout(() => {
      if (settled) return;
      settled = true;
      reject(new Error('Транзакция локального хранилища не завершилась вовремя'));
    }, timeoutMs);
    const finish = (error) => {
      if (settled) return;
      settled = true;
      clearTimeout(timeout);
      if (error) reject(error); else resolve();
    };
    transaction.oncomplete = () => finish();
    transaction.onabort = () => finish(transaction.error || new Error('Операция локального хранилища отменена'));
    transaction.onerror = () => finish(transaction.error || new Error('Ошибка локального хранилища'));
  });
}

async function openRecoveryDatabase(indexedDBFactory = globalThis.indexedDB) {
  if (!indexedDBFactory?.open) throw new Error('IndexedDB недоступен в этом браузере');
  const request = indexedDBFactory.open(RECOVERY_DB_NAME, 1);
  request.onupgradeneeded = () => {
    const database = request.result;
    if (!database.objectStoreNames.contains(RECOVERY_STORE_NAME)) database.createObjectStore(RECOVERY_STORE_NAME);
  };
  return new Promise((resolve, reject) => {
    let settled = false;
    const timeout = setTimeout(() => {
      if (settled) return;
      settled = true;
      reject(new Error('Локальное хранилище автосохранения не ответило вовремя'));
    }, 750);
    request.onsuccess = () => {
      if (settled) { request.result?.close?.(); return; }
      settled = true;
      clearTimeout(timeout);
      resolve(request.result);
    };
    request.onerror = () => {
      if (settled) return;
      settled = true;
      clearTimeout(timeout);
      reject(request.error || new Error('Ошибка локального хранилища'));
    };
    request.onblocked = () => {
      if (settled) return;
      settled = true;
      clearTimeout(timeout);
      reject(new Error('Локальное хранилище автосохранения заблокировано другой вкладкой'));
    };
  });
}
function makeRecoveryRecord(snapshots, doc = {}, savedAt = Date.now()) {
  const input = Array.isArray(snapshots) ? snapshots : [{ snapshot: snapshots, ...doc }];
  if (!input.length || input.some(item => typeof item?.snapshot !== 'string' || !item.snapshot.trim())) {
    throw new Error('Пустой снимок автосохранения');
  }
  return {
    version: RECOVERY_RECORD_VERSION,
    savedAt: Number.isFinite(Number(savedAt)) ? Number(savedAt) : Date.now(),
    activeIndex: Math.min(Math.max(0, Number(doc?.activeIndex) || 0), input.length - 1),
    documents: input.map(item => ({
      docName: String(item?.docName || item?.name || 'Без имени').slice(0, 240),
      modifiedAt: typeof item?.modifiedAt === 'string' ? item.modifiedAt : '',
      snapshot: item.snapshot,
    })),
  };
}
function normalizeRecoveryRecord(value) {
  if (!value || ![1, RECOVERY_RECORD_VERSION].includes(value.version)) return null;
  const savedAt = Number(value.savedAt);
  if (!Number.isFinite(savedAt) || savedAt <= 0) return null;
  const documents = value.version === 1 ? [value] : value.documents;
  if (!Array.isArray(documents) || !documents.length) return null;
  const validDocuments = documents.map((item, index) => ({ item, index }))
    .filter(({ item }) => typeof item?.snapshot === 'string' && item.snapshot.trim());
  if (!validDocuments.length) return null;
  const originalActiveIndex = Number(value.activeIndex);
  const activeIndex = Number.isInteger(originalActiveIndex)
    ? Math.max(0, validDocuments.findIndex(({ index }) => index === originalActiveIndex)) : 0;
  return {
    version: RECOVERY_RECORD_VERSION, savedAt,
    activeIndex,
    documents: validDocuments.map(({ item }) => ({
      docName: String(item.docName || 'Без имени').slice(0, 240),
      modifiedAt: typeof item.modifiedAt === 'string' ? item.modifiedAt : '',
      snapshot: item.snapshot,
    })),
  };
}
async function saveRecoverySnapshot(snapshot, doc, { indexedDBFactory = globalThis.indexedDB, key = RECOVERY_KEY } = {}) {
  const database = await openRecoveryDatabase(indexedDBFactory);
  try {
    const transaction = database.transaction(RECOVERY_STORE_NAME, 'readwrite');
    transaction.objectStore(RECOVERY_STORE_NAME).put(makeRecoveryRecord(snapshot, doc), key);
    await transactionDone(transaction);
  } finally {
    database.close();
  }
}
async function loadRecoverySnapshot({ indexedDBFactory = globalThis.indexedDB } = {}) {
  const database = await openRecoveryDatabase(indexedDBFactory);
  try {
    const transaction = database.transaction(RECOVERY_STORE_NAME, 'readonly');
    const request = transaction.objectStore(RECOVERY_STORE_NAME).get(RECOVERY_KEY);
    const [value] = await Promise.all([requestResult(request), transactionDone(transaction)]);
    return normalizeRecoveryRecord(value);
  } finally {
    database.close();
  }
}
async function loadRecoverySnapshots({ indexedDBFactory = globalThis.indexedDB, includeInvalid = false } = {}) {
  const database = await openRecoveryDatabase(indexedDBFactory);
  try {
    const transaction = database.transaction(RECOVERY_STORE_NAME, 'readonly');
    const store = transaction.objectStore(RECOVERY_STORE_NAME);
    const keysRequest = store.getAllKeys();
    const recordsRequest = store.getAll();
    const [[keys, records]] = await Promise.all([
      Promise.all([requestResult(keysRequest), requestResult(recordsRequest)]),
      transactionDone(transaction),
    ]);
    const entries = keys.map((key, index) => ({ key, record: normalizeRecoveryRecord(records[index]) }));
    return includeInvalid ? entries : entries.filter(item => item.record);
  } finally {
    database.close();
  }
}
async function clearRecoverySnapshot({ indexedDBFactory = globalThis.indexedDB, key = RECOVERY_KEY } = {}) {
  const database = await openRecoveryDatabase(indexedDBFactory);
  try {
    const transaction = database.transaction(RECOVERY_STORE_NAME, 'readwrite');
    transaction.objectStore(RECOVERY_STORE_NAME).delete(key);
    await transactionDone(transaction);
  } finally {
    database.close();
  }
}

// ---- src/core/layer-styles.js ----
// Layer styles are stored with the layer, not baked into its source pixels.
const LAYER_STYLE_FIELDS = Object.freeze({
  stroke: { label:'Обводка', fields:{size:['range',1,24,5],color:['color','#4f8cff'],opacity:['range',0,100,100]} },
  bevel: { label:'Тиснение', fields:{size:['range',1,24,6],strength:['range',0,100,60],angle:['range',0,360,135]} },
  innerShadow: { label:'Внутренняя тень', fields:{distance:['range',0,40,6],blur:['range',0,40,10],color:['color','#000000'],opacity:['range',0,100,55]} },
  innerGlow: { label:'Внутреннее свечение', fields:{blur:['range',1,40,12],color:['color','#ffffff'],opacity:['range',0,100,65]} },
  colorOverlay: { label:'Наложение цвета', fields:{color:['color','#4f8cff'],opacity:['range',0,100,100]} },
  gradientOverlay: { label:'Наложение градиента', fields:{color1:['color','#4f8cff'],color2:['color','#ff7ab6'],angle:['range',0,360,0],opacity:['range',0,100,100]} },
  patternOverlay: { label:'Наложение узора', fields:{pattern:['select',['stripes','dots','checker'],'stripes'],color:['color','#ffffff'],scale:['range',4,48,14],opacity:['range',0,100,70]} },
  outerGlow: { label:'Внешнее свечение', fields:{blur:['range',1,40,16],color:['color','#79aaff'],opacity:['range',0,100,70]} },
  dropShadow: { label:'Тень', fields:{distance:['range',0,80,12],blur:['range',0,40,16],angle:['range',0,360,135],color:['color','#000000'],opacity:['range',0,100,65]} },
});
function createLayerStyles() {
  const result={fillOpacity:100};
  for(const [key,spec] of Object.entries(LAYER_STYLE_FIELDS)) {
    result[key]={enabled:false};
    for(const [field,rule] of Object.entries(spec.fields)) result[key][field]=rule[0]==='range'?rule[3]:rule[0]==='color'?rule[1]:rule[2];
  }
  return result;
}
function sanitizeLayerStyles(value) {
  if(!value || typeof value!=='object' || Array.isArray(value)) return null;
  const result=createLayerStyles();
  const fill=Number(value.fillOpacity);
  if(Number.isFinite(fill)) result.fillOpacity=Math.max(0,Math.min(100,Math.round(fill)));
  for(const [key,spec] of Object.entries(LAYER_STYLE_FIELDS)) {
    const input=value[key];
    if(!input || typeof input!=='object' || Array.isArray(input)) continue;
    result[key].enabled=input.enabled===true;
    for(const [field,rule] of Object.entries(spec.fields)) {
      const candidate=input[field];
      if(rule[0]==='range') {
        const number=Number(candidate);
        if(Number.isFinite(number))result[key][field]=Math.max(rule[1],Math.min(rule[2],Math.round(number)));
      } else if(rule[0]==='color') {
        if(typeof candidate==='string' && /^#[\da-f]{6}$/i.test(candidate)) result[key][field]=candidate.toLowerCase();
      } else if(rule[0]==='select' && rule[1].includes(candidate)) result[key][field]=candidate;
    }
  }
  return result;
}
function hasLayerStyles(value) {
  return Boolean(value && (Number(value.fillOpacity)<100 || Object.keys(LAYER_STYLE_FIELDS).some(key=>value[key]?.enabled===true)));
}
function layerStyleOutset(value) {
  const s=sanitizeLayerStyles(value);
  if(!s)return 0;
  return Math.max(0,
    s.stroke.enabled?s.stroke.size+2:0,
    s.outerGlow.enabled?s.outerGlow.blur*2+2:0,
    s.dropShadow.enabled?s.dropShadow.distance+s.dropShadow.blur*2+2:0,
    s.innerGlow.enabled?s.innerGlow.blur*2+2:0,
    s.innerShadow.enabled?s.innerShadow.distance+s.innerShadow.blur*2+2:0,
    s.bevel.enabled?s.bevel.size*3+2:0);
}

function canvas(width,height) {
  const item=document.createElement('canvas');
  item.width=width;item.height=height;
  return item;
}

// The styled group is composited once by renderLayer, so layer opacity and blend mode
// apply to the whole effect rather than repeatedly to each style.
async function renderLayerStyles(styles,width,height,paint,{contentBlur=0}={}) {
  const s=sanitizeLayerStyles(styles);
  const active=Object.entries(LAYER_STYLE_FIELDS).filter(([key])=>s[key].enabled).map(([key])=>key);
  const outside=Math.max(2,contentBlur*2+2,layerStyleOutset(s));
  // Bound temporary Canvas memory for large documents. All dimensions and radii
  // scale together; the saved source pixels and project data remain untouched.
  const scale=Math.min(1,Math.sqrt(16_000_000/((width+outside*2)*(height+outside*2))));
  const w=Math.max(1,Math.ceil(width*scale)),h=Math.max(1,Math.ceil(height*scale));
  const pad=Math.max(2,Math.ceil(outside*scale));
  const cw=w+pad*2,ch=h+pad*2;
  const source=canvas(cw,ch),sourceCtx=source.getContext('2d',{alpha:true});
  sourceCtx.scale(scale,scale);
  sourceCtx.translate(pad/scale,pad/scale);
  await paint(sourceCtx);
  const output=canvas(cw,ch),out=output.getContext('2d',{alpha:true});
  const scratch=canvas(cw,ch),temp=scratch.getContext('2d',{alpha:true});
  let inverse=null;
  const reset=()=>{temp.setTransform(1,0,0,1,0,0);temp.globalAlpha=1;temp.globalCompositeOperation='source-over';temp.filter='none';temp.shadowColor='transparent';temp.shadowBlur=0;temp.shadowOffsetX=0;temp.shadowOffsetY=0;temp.clearRect(0,0,cw,ch);};
  const commit=()=>out.drawImage(scratch,0,0);
  const tint=(color,opacity)=>{
    temp.globalCompositeOperation='source-in';temp.globalAlpha=opacity/100;temp.fillStyle=color;temp.fillRect(0,0,cw,ch);
  };
  const outer=(item,dx,dy)=>{
    reset();
    temp.shadowColor=item.color;temp.shadowBlur=item.blur*scale;
    temp.shadowOffsetX=dx*scale;temp.shadowOffsetY=dy*scale;
    temp.drawImage(source,0,0);
    temp.shadowColor='transparent';temp.shadowBlur=0;temp.shadowOffsetX=0;temp.shadowOffsetY=0;
    temp.globalCompositeOperation='destination-out';temp.drawImage(source,0,0);
    tint(item.color,item.opacity);commit();
  };
  const inner=(color,opacity,blur,dx,dy)=>{
    if(!inverse){
      inverse=canvas(cw,ch);
      const mask=inverse.getContext('2d',{alpha:true});
      mask.fillStyle='#fff';mask.fillRect(0,0,cw,ch);
      mask.globalCompositeOperation='destination-out';mask.drawImage(source,0,0);
    }
    reset();
    temp.shadowColor=color;temp.shadowBlur=blur*scale;
    temp.shadowOffsetX=dx*scale;temp.shadowOffsetY=dy*scale;
    temp.drawImage(inverse,0,0);
    temp.shadowColor='transparent';temp.shadowBlur=0;temp.shadowOffsetX=0;temp.shadowOffsetY=0;
    temp.globalCompositeOperation='destination-in';temp.drawImage(source,0,0);
    tint(color,opacity);commit();
  };
  if(active.includes('dropShadow')){
    const item=s.dropShadow,angle=item.angle*Math.PI/180;
    outer(item,Math.cos(angle)*item.distance,Math.sin(angle)*item.distance);
  }
  if(active.includes('outerGlow'))outer(s.outerGlow,0,0);
  if(active.includes('stroke')){
    const item=s.stroke;reset();
    for(let step=0;step<24;step++){
      const angle=step*Math.PI/12;
      temp.drawImage(source,Math.cos(angle)*item.size*scale,Math.sin(angle)*item.size*scale);
    }
    tint(item.color,item.opacity);
    temp.globalCompositeOperation='destination-out';temp.globalAlpha=1;temp.drawImage(source,0,0);
    commit();
  }
  out.globalAlpha=s.fillOpacity/100;out.drawImage(source,0,0);out.globalAlpha=1;
  const overlay=(item,fill)=>{
    reset();temp.drawImage(source,0,0);
    temp.globalCompositeOperation='source-in';temp.globalAlpha=item.opacity/100;
    temp.fillStyle=fill;temp.fillRect(0,0,cw,ch);commit();
  };
  if(active.includes('colorOverlay'))overlay(s.colorOverlay,s.colorOverlay.color);
  if(active.includes('gradientOverlay')){
    const item=s.gradientOverlay,angle=item.angle*Math.PI/180;
    const cx=pad+w/2,cy=pad+h/2,reach=Math.hypot(w,h)/2;
    const gradient=temp.createLinearGradient(cx-Math.cos(angle)*reach,cy-Math.sin(angle)*reach,cx+Math.cos(angle)*reach,cy+Math.sin(angle)*reach);
    gradient.addColorStop(0,item.color1);gradient.addColorStop(1,item.color2);
    overlay(item,gradient);
  }
  if(active.includes('patternOverlay')){
    const item=s.patternOverlay,size=Math.max(2,Math.round(item.scale*scale));
    const tile=canvas(size*2,size*2),tileCtx=tile.getContext('2d',{alpha:true});
    tileCtx.fillStyle=item.color;
    if(item.pattern==='checker'){tileCtx.fillRect(0,0,size,size);tileCtx.fillRect(size,size,size,size);}
    else if(item.pattern==='dots'){
      tileCtx.beginPath();tileCtx.arc(size/2,size/2,Math.max(1,size/3),0,Math.PI*2);tileCtx.arc(size*1.5,size*1.5,Math.max(1,size/3),0,Math.PI*2);tileCtx.fill();
    } else {for(let x=-size*2;x<size*4;x+=size){tileCtx.beginPath();tileCtx.moveTo(x,0);tileCtx.lineTo(x+size*2,size*2);tileCtx.lineTo(x+size*2+Math.max(1,size/3),size*2);tileCtx.lineTo(x+Math.max(1,size/3),0);tileCtx.closePath();tileCtx.fill();}}
    overlay(item,temp.createPattern(tile,'repeat'));
  }
  if(active.includes('innerGlow'))inner(s.innerGlow.color,s.innerGlow.opacity,s.innerGlow.blur,0,0);
  if(active.includes('innerShadow')){
    const item=s.innerShadow,angle=135*Math.PI/180;
    inner(item.color,item.opacity,item.blur,Math.cos(angle)*item.distance,Math.sin(angle)*item.distance);
  }
  if(active.includes('bevel')){
    const item=s.bevel,angle=item.angle*Math.PI/180,dx=Math.cos(angle)*item.size,dy=Math.sin(angle)*item.size;
    inner('#ffffff',item.strength,item.size,-dx,-dy);
    inner('#000000',item.strength,item.size,dx,dy);
  }
  return {canvas:output,x:-pad/scale,y:-pad/scale,width:cw/scale,height:ch/scale};
}

// ---- src/core/adjustments.js ----
const clampAdjustment=(value,min,max,fallback=0)=>{
  const number=Number(value);
  return Number.isFinite(number)?Math.max(min,Math.min(max,number)):fallback;
};
const intAdjustment=(value,min,max,fallback=0)=>Math.round(clampAdjustment(value,min,max,fallback));

function sanitizeLevelRecord(value={}) {
  const inputBlack=intAdjustment(value.inputBlack,0,253,0);
  const inputWhite=Math.max(inputBlack+2,intAdjustment(value.inputWhite,2,255,255));
  const outputBlack=intAdjustment(value.outputBlack,0,255,0);
  const outputWhite=intAdjustment(value.outputWhite,0,255,255);
  return{
    inputBlack,
    inputWhite:Math.min(255,inputWhite),
    gamma:clampAdjustment(value.gamma,.1,9.99,1),
    outputBlack,
    outputWhite,
  };
}

function sanitizeCurvePoints(points) {
  const clean=(Array.isArray(points)?points:[])
    .slice(0,19)
    .map(point=>({
      input:intAdjustment(point?.input,0,255,0),
      output:intAdjustment(point?.output,0,255,0),
    }))
    .sort((a,b)=>a.input-b.input||a.output-b.output);
  const unique=[];
  for(const point of clean){
    if(unique.length&&unique.at(-1).input===point.input)unique[unique.length-1]=point;
    else unique.push(point);
  }
  return unique;
}
function sanitizeAdjustmentModel(value) {
  if(!value||typeof value!=='object'||Array.isArray(value))return null;
  const kind=String(value.kind||'');
  if(kind==='brightness-contrast'){
    return{kind,brightness:intAdjustment(value.brightness,-150,150,0),contrast:intAdjustment(value.contrast,-100,100,0),legacy:value.legacy===true};
  }
  if(kind==='exposure'){
    return{kind,exposure:clampAdjustment(value.exposure,-20,20,0),offset:clampAdjustment(value.offset,-2,2,0),gamma:clampAdjustment(value.gamma,.1,10,1)};
  }
  if(kind==='hue-saturation'){
    const colorize=value.colorize===true;
    return{kind,hue:intAdjustment(value.hue,-180,180,0),saturation:intAdjustment(value.saturation,colorize?0:-100,100,0),lightness:intAdjustment(value.lightness,-100,100,0),colorize};
  }
  if(kind==='invert')return{kind};
  if(kind==='posterize')return{kind,levels:intAdjustment(value.levels,2,255,4)};
  if(kind==='threshold')return{kind,level:intAdjustment(value.level,1,255,128)};
  if(kind==='levels'){
    const channels=Array.isArray(value.channels)?value.channels.slice(0,8).map((entry,index)=>({
      id:intAdjustment(entry?.id,-1,32,index),
      ...sanitizeLevelRecord(entry),
    })):[];
    return{kind,master:sanitizeLevelRecord(value.master),channels};
  }
  if(kind==='curves'){
    const channels=(Array.isArray(value.channels)?value.channels:[]).slice(0,16).map((entry,index)=>({
      id:intAdjustment(entry?.id,0,31,index),
      points:sanitizeCurvePoints(entry?.points),
    })).filter(entry=>entry.points.length>=2);
    return{kind,channels};
  }
  return null;
}

function applyBrightnessContrast01(value,brightness,contrast) {
  const bright=Math.max(-1,Math.min(1,brightness/150));
  let x=bright>=0?value+(1-value)*bright:value*(1+bright);
  const c=Math.max(-254,Math.min(254,contrast*2.54));
  const factor=(259*(c+255))/(255*(259-c));
  x=factor*(x-.5)+.5;
  return Math.max(0,Math.min(1,x));
}

function rgbToHsl(r,g,b) {
  const max=Math.max(r,g,b),min=Math.min(r,g,b),delta=max-min;
  let h=0;
  if(delta){
    if(max===r)h=((g-b)/delta)%6;
    else if(max===g)h=(b-r)/delta+2;
    else h=(r-g)/delta+4;
    h*=60;if(h<0)h+=360;
  }
  const l=(max+min)/2;
  const s=delta===0?0:delta/(1-Math.abs(2*l-1));
  return[h,s,l];
}
function hslToRgb(h,s,l) {
  const c=(1-Math.abs(2*l-1))*s;
  const hp=((h%360)+360)%360/60;
  const x=c*(1-Math.abs((hp%2)-1));
  let r=0,g=0,b=0;
  if(hp<1){r=c;g=x}else if(hp<2){r=x;g=c}else if(hp<3){g=c;b=x}else if(hp<4){g=x;b=c}else if(hp<5){r=x;b=c}else{r=c;b=x}
  const m=l-c/2;
  return[r+m,g+m,b+m];
}

function applyLevels01(value,record) {
  const inputBlack=record.inputBlack/255,inputWhite=record.inputWhite/255;
  let x=(value-inputBlack)/Math.max(1/255,inputWhite-inputBlack);
  x=Math.max(0,Math.min(1,x));
  x=Math.pow(x,1/Math.max(.1,record.gamma));
  const outputBlack=record.outputBlack/255,outputWhite=record.outputWhite/255;
  return Math.max(0,Math.min(1,outputBlack+x*(outputWhite-outputBlack)));
}

function curveValue(value,points) {
  if(!points?.length)return value;
  const x=Math.max(0,Math.min(255,value*255));
  if(x<=points[0].input)return points[0].output/255;
  if(x>=points.at(-1).input)return points.at(-1).output/255;
  for(let index=1;index<points.length;index+=1){
    const right=points[index],left=points[index-1];
    if(x<=right.input){
      const t=(x-left.input)/Math.max(1,right.input-left.input);
      return Math.max(0,Math.min(1,(left.output+(right.output-left.output)*t)/255));
    }
  }
  return value;
}
function applyAdjustmentPixels(imageData,adjustment) {
  if(!imageData?.data)return imageData;
  const model=sanitizeAdjustmentModel(adjustment);
  if(!model)return imageData;
  const data=imageData.data;
  for(let index=0;index<data.length;index+=4){
    if(data[index+3]===0)continue;
    let r=data[index]/255,g=data[index+1]/255,b=data[index+2]/255;
    if(model.kind==='brightness-contrast'){
      r=applyBrightnessContrast01(r,model.brightness,model.contrast);
      g=applyBrightnessContrast01(g,model.brightness,model.contrast);
      b=applyBrightnessContrast01(b,model.brightness,model.contrast);
    }else if(model.kind==='exposure'){
      const scale=2**model.exposure,power=1/Math.max(.1,model.gamma);
      r=Math.pow(Math.max(0,r*scale+model.offset),power);
      g=Math.pow(Math.max(0,g*scale+model.offset),power);
      b=Math.pow(Math.max(0,b*scale+model.offset),power);
    }else if(model.kind==='hue-saturation'){
      let[h,s,l]=rgbToHsl(r,g,b);
      if(model.colorize){h=((model.hue%360)+360)%360;s=Math.max(0,Math.min(1,model.saturation/100));}
      else{h=(h+model.hue+360)%360;s=Math.max(0,Math.min(1,s*(1+model.saturation/100)));}
      l=Math.max(0,Math.min(1,l+model.lightness/100));
      [r,g,b]=hslToRgb(h,s,l);
    }else if(model.kind==='invert'){
      r=1-r;g=1-g;b=1-b;
    }else if(model.kind==='posterize'){
      const levels=model.levels;
      const correction=255/256;
      r=Math.floor(correction*r*levels)/(levels-1);
      g=Math.floor(correction*g*levels)/(levels-1);
      b=Math.floor(correction*b*levels)/(levels-1);
    }else if(model.kind==='threshold'){
      const luminance=Math.round((.3*r+.59*g+.11*b)*255);
      const value=luminance>=model.level?1:0;
      r=value;g=value;b=value;
    }else if(model.kind==='levels'){
      r=applyLevels01(r,model.master);g=applyLevels01(g,model.master);b=applyLevels01(b,model.master);
      const byId=new Map(model.channels.map(entry=>[entry.id,entry]));
      if(byId.has(1))r=applyLevels01(r,byId.get(1));
      if(byId.has(2))g=applyLevels01(g,byId.get(2));
      if(byId.has(3))b=applyLevels01(b,byId.get(3));
    }else if(model.kind==='curves'){
      const byId=new Map(model.channels.map(entry=>[entry.id,entry.points]));
      const master=byId.get(0);
      if(master){r=curveValue(r,master);g=curveValue(g,master);b=curveValue(b,master);}
      if(byId.has(1))r=curveValue(r,byId.get(1));
      if(byId.has(2))g=curveValue(g,byId.get(2));
      if(byId.has(3))b=curveValue(b,byId.get(3));
    }
    data[index]=Math.round(Math.max(0,Math.min(1,r))*255);
    data[index+1]=Math.round(Math.max(0,Math.min(1,g))*255);
    data[index+2]=Math.round(Math.max(0,Math.min(1,b))*255);
  }
  return imageData;
}

function blendAdjustmentChannel(base,effect,mode) {
  if(mode==='multiply')return base*effect;
  if(mode==='screen')return 1-(1-base)*(1-effect);
  if(mode==='overlay')return base<=.5?2*base*effect:1-2*(1-base)*(1-effect);
  if(mode==='soft-light'){
    const d=base<=.25?((16*base-12)*base+4)*base:Math.sqrt(base);
    return effect<=.5
      ? base-(1-2*effect)*base*(1-base)
      : base+(2*effect-1)*(d-base);
  }
  if(mode==='hard-light')return effect<=.5?2*base*effect:1-2*(1-base)*(1-effect);
  if(mode==='darken')return Math.min(base,effect);
  if(mode==='lighten')return Math.max(base,effect);
  if(mode==='color-dodge')return effect>=1?1:Math.min(1,base/(1-effect));
  if(mode==='color-burn')return effect<=0?0:1-Math.min(1,(1-base)/effect);
  if(mode==='difference')return Math.abs(base-effect);
  if(mode==='exclusion')return base+effect-2*base*effect;
  return effect;
}
function compositeAdjustmentPixels(baseImageData,effectImageData,{opacity=1,blendMode='source-over'}={}) {
  if(!baseImageData?.data||!effectImageData?.data||baseImageData.data.length!==effectImageData.data.length)return baseImageData;
  const layerOpacity=clampAdjustment(opacity,0,1,1);
  if(layerOpacity<=0)return baseImageData;
  const base=baseImageData.data,effect=effectImageData.data;
  for(let index=0;index<base.length;index+=4){
    const baseAlpha=base[index+3];
    const effectAlpha=effect[index+3];
    if(baseAlpha<=0||effectAlpha<=0)continue;
    const coverage=Math.min(1,effectAlpha/baseAlpha)*layerOpacity;
    if(coverage<=0)continue;
    for(let channel=0;channel<3;channel+=1){
      const original=base[index+channel]/255;
      const adjusted=effect[index+channel]/255;
      const blended=blendAdjustmentChannel(original,adjusted,blendMode);
      base[index+channel]=Math.round(Math.max(0,Math.min(1,original+(blended-original)*coverage))*255);
    }
  }
  return baseImageData;
}
function adjustmentModelEqual(left,right) {
  return JSON.stringify(sanitizeAdjustmentModel(left))===JSON.stringify(sanitizeAdjustmentModel(right));
}

// ---- src/core/state.js ----
let layerCounter = 0;
const uid = (prefix = 'layer') => `${prefix}-${Date.now().toString(36)}-${(++layerCounter).toString(36)}`;
const finite = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
